const PEPS=[
  {id:'bpc157',n:'BPC-157',fn:'Body Protective Compound 157',cat:'healing',ov:'Synthetic pentadecapeptide isolated from human gastric juice. The most versatile and extensively researched healing peptide with documented effects across multiple tissue types and a remarkable 30+ year safety record.',mech:'Upregulates VEGF for angiogenesis, activates growth hormone receptors locally, stimulates nitric oxide synthase, and modulates FAK-paxillin signaling to dramatically accelerate tissue repair.',dose:'200–500 mcg/day',freq:'Once or twice daily',hl:'~4 hours',hlh:4,admin:'SubQ · IM · Oral',store:'Lyophilized: room temp. Reconstituted: 2–8°C, use within 30 days.',recon:'Add 1–2 ml bacteriostatic water per 5mg vial. Swirl gently, never shake.',bens:['Tendon and ligament repair','Gut lining healing (IBS, leaky gut)','Systemic anti-inflammatory','Joint and bone protection','CNS neuroprotective effects'],sides:['Nausea (uncommon)','Mild dizziness at high doses','Transient fatigue'],status:'Preclinical',pop:99,rel:['tb500','ghkcu','kpv','ara290','larazotide']},
  {id:'tb500',n:'TB-500',fn:'Thymosin Beta-4 Synthetic Fragment',cat:'healing',ov:'Synthetic analogue of Thymosin Beta-4, a naturally occurring protein found in virtually all cells. Exceptional systemic healing with strong anti-inflammatory properties, particularly effective for muscle and soft tissue injuries.',mech:'Promotes actin polymerization and cell migration, stimulates angiogenesis and lymphangiogenesis, upregulates laminin-5, and modulates inflammatory cytokine production throughout the body.',dose:'2–2.5 mg, 2x weekly (loading); 2–2.5 mg weekly (maintenance)',freq:'2x weekly loading then weekly maintenance',hl:'Estimated days',hlh:72,admin:'SubQ · IM',store:'Lyophilized: room temp or refrigerated. Reconstituted: 2–8°C.',recon:'Add 1–2 ml bacteriostatic water per 5mg vial. Swirl gently.',bens:['Systemic muscle and soft tissue repair','Improved flexibility and ROM','Reduced scar tissue formation','Enhanced cardiovascular tissue repair','Anti-inflammatory throughout body'],sides:['Fatigue during loading phase','Mild nausea','Occasional headache'],status:'Preclinical',pop:92,rel:['bpc157','ghkcu','thymosinbeta4']},
  {id:'ghkcu',n:'GHK-Cu',fn:'Glycine-Histidine-Lysine Copper Peptide',cat:'healing',ov:'Naturally occurring copper-binding tripeptide found in human plasma. Levels decline with age, correlating with reduced regeneration. Activates over 4,000 genes involved in tissue remodeling.',mech:'Activates wound-healing and regeneration genes, stimulates collagen and elastin synthesis, acts as a potent antioxidant, and modulates both pro- and anti-inflammatory signaling at the transcriptional level.',dose:'2–4 mg/day injectable; 1–3% topical',freq:'Once daily; topical 1–2x daily',hl:'~1–2 hours',hlh:1.5,admin:'SubQ · Topical',store:'Refrigerate reconstituted injectable. Topical: room temp in dark container.',recon:'Add 1–2 ml bacteriostatic water. Can be incorporated into topical formulations.',bens:['Collagen and elastin synthesis','Wound healing acceleration','Cellular-level anti-aging','Hair follicle stimulation','Antioxidant protection'],sides:['Local redness topical','Mild skin irritation initially','Metallic taste at high injectable doses'],status:'Preclinical',pop:78,rel:['bpc157','epithalon','matrixyl','argireline','ahkcu']},
  {id:'ll37',n:'LL-37',fn:'Cathelicidin Antimicrobial Peptide LL-37',cat:'healing',ov:'The only known human cathelicidin — a critical frontline defense peptide central to innate immunity. Simultaneously directs wound healing, angiogenesis, and immune modulation.',mech:'Disrupts microbial membrane integrity, promotes keratinocyte migration for wound closure, stimulates VEGF-A for angiogenesis, and modulates both pro- and anti-inflammatory cytokine release.',dose:'100–500 mcg/day',freq:'Once daily',hl:'~2–4 hours',hlh:3,admin:'SubQ · Topical',store:'Refrigerate reconstituted. Avoid repeated freeze-thaw cycles.',recon:'Add 1 ml bacteriostatic water per vial. Use within 2–3 weeks.',bens:['Broad-spectrum antimicrobial','Accelerated wound healing','Immune system modulation','Anti-biofilm properties','Angiogenesis promotion'],sides:['Injection site reaction','Inflammation at high doses','Limited human data'],status:'Clinical (Phase I/II)',pop:45,rel:['bpc157','kpv','ara290']},
  {id:'kpv',n:'KPV',fn:'Lysine-Proline-Valine Anti-inflammatory Tripeptide',cat:'healing',ov:'C-terminal tripeptide of alpha-MSH with potent anti-inflammatory properties. Particularly effective for intestinal inflammation, making it highly relevant for IBD and Crohn\'s disease research.',mech:'Inhibits NF-kB signaling, reduces pro-inflammatory cytokines including IL-6 and TNF-alpha, and directly acts on cellular receptors to suppress inflammatory cascades in intestinal epithelial cells.',dose:'500 mcg – 1 mg/day',freq:'Once to twice daily',hl:'~2 hours',hlh:2,admin:'SubQ · Oral',store:'Refrigerate reconstituted. Oral capsule: room temp in sealed container.',recon:'Add 1 ml bacteriostatic water. Oral particularly effective for gut targeting.',bens:['Gut inflammation and IBD support','Crohns and colitis research','Systemic anti-inflammatory','Colonic healing and repair','Microbiome-supportive'],sides:['Minimal reported side effects','Very limited human safety data'],status:'Preclinical',pop:55,rel:['bpc157','ll37']},
  {id:'ipamorelin',n:'Ipamorelin',fn:'Ipamorelin — 5th Generation GHRP',cat:'gh',ov:'Fifth-generation growth hormone secretagogue that mimics ghrelin with exceptional selectivity. Stimulates GH pulses without affecting cortisol or prolactin — the cleanest GHRP and gold standard for GH optimization.',mech:'Binds selectively to ghrelin/GHS-R1a receptors on pituitary somatotrophs, stimulating pulsatile GH release while maintaining minimal off-target receptor activity and preserving normal GH feedback.',dose:'200–300 mcg/dose',freq:'1–3x daily; best dosed pre-sleep',hl:'~2 hours',hlh:2,admin:'SubQ · IM',store:'Refrigerate reconstituted. Dry peptide: room temp or fridge.',recon:'Add 1–2 ml bacteriostatic water per 5mg vial. Common: 100 mcg/ml concentration.',bens:['Clean pulsatile GH stimulation','Improved deep sleep quality','Body composition improvement','Recovery enhancement','Anti-aging via IGF-1 elevation'],sides:['Water retention','Tingling at injection site','Mild headache','Increased appetite'],status:'Preclinical',pop:93,rel:['cjc1295','sermorelin','ghrp6','ghrp2','somatropin']},
  {id:'cjc1295',n:'CJC-1295',fn:'CJC-1295 GHRH Analogue with DAC',cat:'gh',ov:'GHRH analogue modified with DAC technology allowing albumin binding and extending half-life from 30 min to 6–8 days. Combined with Ipamorelin produces synergistic GH amplification.',mech:'Binds GHRH receptors on pituitary somatotrophs. The DAC modification creates a covalent bond with albumin, maintaining continuous receptor stimulation for nearly a week per injection.',dose:'1–2 mg, 1–2x weekly (DAC); 100–200 mcg 2–3x daily (no DAC)',freq:'Weekly (DAC) or 2–3x daily (no DAC)',hl:'6–8 days (DAC) / 30 min (no DAC)',hlh:168,admin:'SubQ',store:'Refrigerate reconstituted. Stable up to 3 months refrigerated.',recon:'Add 1–2 ml bacteriostatic water. DAC: commonly 1mg/ml concentration.',bens:['Sustained GH elevation all week','IGF-1 increase','Muscle growth support','Enhanced fat metabolism','Improved recovery and sleep'],sides:['Water retention','Potential insulin resistance long-term','Facial flushing','Headache'],status:'Preclinical',pop:88,rel:['ipamorelin','sermorelin','ghrp6','ghrp2','grf144','somatropin']},
  {id:'sermorelin',n:'Sermorelin',fn:'GHRH(1-29) Growth Hormone Releasing Hormone',cat:'gh',ov:'First 29 amino acids of endogenous GHRH. The first GHRH analogue to receive FDA approval for pediatric GH deficiency. One of the most clinically studied GH secretagogues.',mech:'Directly stimulates GHRH receptors on pituitary somatotrophs, mimicking endogenous GHRH to increase GH synthesis and secretion in a physiological pulsatile pattern.',dose:'200–500 mcg/day',freq:'Once daily, pre-sleep',hl:'~11 minutes',hlh:0.18,admin:'SubQ',store:'Refrigerate reconstituted. Use within 30 days.',recon:'Add 1–2 ml bacteriostatic water per vial.',bens:['Physiological GH stimulation','IGF-1 normalization','Improved sleep architecture','Body composition support','Established clinical safety'],sides:['Facial flushing','Injection site discomfort','Headache','Tachycardia rare'],status:'FDA Approved (historical)',pop:72,rel:['ipamorelin','cjc1295','grf144','somatropin']},
  {id:'ghrp6',n:'GHRP-6',fn:'Growth Hormone Releasing Peptide 6',cat:'gh',ov:'Hexapeptide with potent GH-releasing properties. Notable for significantly increasing appetite alongside GH release — useful for mass-gaining protocols. One of the original GHRPs.',mech:'Acts on ghrelin receptors in both the pituitary and hypothalamus. Stimulates ghrelin release leading to potent GH secretion alongside substantial appetite stimulation via central mechanisms.',dose:'100–300 mcg/dose',freq:'2–3x daily on empty stomach',hl:'15–60 minutes',hlh:0.5,admin:'SubQ · IM',store:'Refrigerate reconstituted. Dry peptide stable at room temp.',recon:'Add 1–2 ml bacteriostatic water per vial.',bens:['Strong GH release response','Significant appetite stimulation','IGF-1 elevation','Muscle mass support','Gastroprotective properties'],sides:['Significant hunger increase','Water retention','Fatigue','Cortisol and prolactin increase'],status:'Preclinical',pop:65,rel:['ipamorelin','cjc1295','hexarelin','ghrp2']},
  {id:'hexarelin',n:'Hexarelin',fn:'Hexarelin (Examorelin)',cat:'gh',ov:'Potent synthetic hexapeptide producing the strongest acute GH release among GHRPs. Notable for direct cardioprotective effects via CD36 receptors independent of GH. Requires regular cycling to prevent desensitization.',mech:'Binds ghrelin receptors with highest affinity among GHRPs. Also directly activates cardiac CD36 receptors for cardioprotection. Inhibits somatostatin and amplifies GHRH-stimulated GH production.',dose:'100–200 mcg/dose',freq:'2–3x daily; cycle off to prevent desensitization',hl:'~70 minutes',hlh:1.2,admin:'SubQ · IM',store:'Refrigerate reconstituted. Dry: room temp.',recon:'Add 1–2 ml bacteriostatic water per vial.',bens:['Most potent acute GH release','Direct cardioprotective mechanism','Anti-inflammatory effects','Tissue repair','GH deficiency applications'],sides:['Rapid tachyphylaxis','Cortisol and prolactin elevation','Appetite increase','Fatigue'],status:'Preclinical',pop:58,rel:['ipamorelin','ghrp6','ghrp2']},
  {id:'mk677',n:'MK-677',fn:'Ibutamoren — Oral GH Secretagogue',cat:'gh',ov:'Non-peptide orally active GH secretagogue mimicking ghrelin\'s GH-stimulating action. Unlike other secretagogues it is taken orally, dramatically increasing both GH and IGF-1 with once-daily dosing.',mech:'Binds and activates the ghrelin receptor in the pituitary and hypothalamus. Increases GH pulse frequency and amplitude, also stimulating IGF-1 secretion from the liver.',dose:'10–25 mg/day orally',freq:'Once daily (oral)',hl:'~24 hours',hlh:24,admin:'Oral',store:'Dry cool dark environment. Tablet or liquid form.',recon:'No reconstitution needed.',bens:['Oral administration no injection','Sustained GH and IGF-1 elevation','Improved sleep depth','Increased bone mineral density','Muscle mass support'],sides:['Significant water retention','Increased appetite','Potential insulin resistance','Lethargy some users'],status:'Phase II',pop:85,rel:['ipamorelin','cjc1295','tabimorelin','somatropin']},
  {id:'semaglutide',n:'Semaglutide',fn:'Semaglutide (Ozempic / Wegovy)',cat:'metabolic',ov:'GLP-1 receptor agonist with 94% sequence homology to human GLP-1. FDA-approved for type 2 diabetes and chronic weight management. Currently the most prescribed peptide globally with landmark trial results.',mech:'Activates GLP-1 receptors in the pancreas, brain hypothalamus, and GI tract. Powerfully reduces caloric intake through multiple complementary mechanisms including gastric emptying delay.',dose:'0.25–2.4 mg/week (titrated monthly)',freq:'Once weekly subcutaneous injection',hl:'~7 days',hlh:168,admin:'SubQ (pen injector)',store:'Unopened: refrigerate 2–8C. In-use pen: room temp up to 28 days.',recon:'Pre-filled pharmaceutical pens. Research grade: sterile saline.',bens:['15–20% mean body weight reduction','Blood glucose and HbA1c reduction','Cardiovascular risk reduction','Significant appetite suppression','Metabolic syndrome improvement'],sides:['Nausea and vomiting most common','Diarrhea or constipation','Pancreatitis risk rare','Gallbladder disease','Theoretical thyroid C-cell risk'],status:'FDA Approved',pop:97,rel:['tirzepatide','liraglutide','aod9604','exenatide','dulaglutide','retatrutide','cagrilintide','pramlintide']},
  {id:'tirzepatide',n:'Tirzepatide',fn:'Tirzepatide (Mounjaro / Zepbound)',cat:'metabolic',ov:'First-in-class dual GLP-1/GIP receptor agonist demonstrating superior weight loss vs semaglutide in SURMOUNT-1 trials. Average 22.5% body weight reduction — the largest ever reported for any pharmaceutical agent.',mech:'Simultaneously activates both GLP-1 and GIP receptors. GIP component amplifies insulinotropic effects and acts directly on adipose tissue, creating greater metabolic impact than GLP-1 agonism alone.',dose:'2.5–15 mg/week (titrated every 4 weeks)',freq:'Once weekly',hl:'~5 days',hlh:120,admin:'SubQ (autoinjector)',store:'Refrigerate 2–8C. Single-use autoinjectors.',recon:'Pharmaceutical preparation only.',bens:['Superior weight loss vs semaglutide 22.5%','Improved insulin sensitivity','Cardiovascular protection','NASH treatment potential','Better HbA1c reduction'],sides:['GI side effects nausea vomiting','Pancreatitis risk','Injection site reactions','Hypoglycemia risk with insulin'],status:'FDA Approved',pop:93,rel:['semaglutide','liraglutide','retatrutide','survodutide']},
  {id:'liraglutide',n:'Liraglutide',fn:'Liraglutide (Victoza / Saxenda)',cat:'metabolic',ov:'GLP-1 receptor agonist with 97% homology to human GLP-1. FDA-approved for type 2 diabetes and weight management. The predecessor to semaglutide with the most extensive long-term safety data in the class.',mech:'Activates GLP-1 receptors in pancreas, brain, and GI tract. Increases insulin secretion, decreases glucagon, slows gastric emptying, and suppresses appetite via hypothalamic signaling.',dose:'0.6–3 mg/day (titrated monthly)',freq:'Once daily injection',hl:'~13 hours',hlh:13,admin:'SubQ (pen)',store:'Unopened: 2–8C. Opened pen: room temp, use within 30 days.',recon:'Pre-filled pharmaceutical pens.',bens:['Proven 5–10% body weight reduction','Extensive long-term safety data','Blood glucose regulation','Cardiovascular protection LEADER trial','Reduced appetite and satiety improvement'],sides:['Nausea and GI side effects','Pancreatitis risk','Gallbladder disease','Theoretical thyroid concerns','Resting heart rate increase'],status:'FDA Approved',pop:78,rel:['semaglutide','tirzepatide','exenatide','dulaglutide']},
  {id:'aod9604',n:'AOD-9604',fn:'HGH Fragment 177-191',cat:'fatloss',ov:'Modified C-terminal fragment of human growth hormone retaining fat-metabolizing properties without growth-promoting effects. Does not bind HGH receptors, affect IGF-1, or influence blood glucose.',mech:'Mimics HGH fat metabolism through a non-HGH receptor pathway. Stimulates lipolysis in adipose tissue and inhibits lipogenesis without the proliferative or diabetogenic effects of full-length HGH.',dose:'300–600 mcg/day',freq:'Once or twice daily empty stomach',hl:'~30 minutes',hlh:0.5,admin:'SubQ',store:'Refrigerate reconstituted. Use within 3–4 weeks.',recon:'Add 1–2 ml bacteriostatic water per vial. Inject fasted.',bens:['Targeted adipose tissue metabolism','No blood glucose impact','No IGF-1 elevation','Potential cartilage repair','Better safety vs full HGH'],sides:['Headache','Mild fatigue','Nausea rare','Limited long-term data'],status:'Phase II/III (TGA Australia)',pop:68,rel:['semaglutide','tesamorelin','adipotide']},
  {id:'tesamorelin',n:'Tesamorelin',fn:'Tesamorelin (Egrifta) — FDA-Approved GHRH Analogue',cat:'fatloss',ov:'Synthetic GHRH analogue FDA-approved for HIV-related lipodystrophy. Considered the gold standard for visceral fat reduction in research, backed by multiple controlled clinical trials.',mech:'Binds GHRH receptors and stimulates endogenous GH secretion, which reduces visceral adipose tissue through lipolytic action while preserving lean body mass.',dose:'1–2 mg/day',freq:'Once daily',hl:'~38 minutes',hlh:0.63,admin:'SubQ',store:'Refrigerate vials. Stable 24 hours reconstituted at room temp.',recon:'Reconstitute with supplied diluent. Do not shake.',bens:['FDA-validated visceral fat reduction','Lean mass preservation','Improved triglyceride levels','GH and IGF-1 normalization','Cardiovascular risk factor improvement'],sides:['Peripheral edema','Arthralgia joint pain','Hyperglycemia risk','Injection site reactions','Nausea'],status:'FDA Approved',pop:74,rel:['aod9604','cjc1295','adipotide']},
  {id:'igf1lr3',n:'IGF-1 LR3',fn:'Insulin-like Growth Factor 1 Long Arg3',cat:'muscle',ov:'Modified IGF-1 analogue with 13x longer half-life than native IGF-1. Primary downstream mediator of GH anabolic effects, directly promoting muscle cell proliferation, differentiation, and satellite cell activation.',mech:'Binds IGF-1 receptor with high affinity, activating protein synthesis via PI3K/Akt/mTOR pathway, promoting satellite cell activation for muscle fiber repair, and inhibiting catabolism.',dose:'20–80 mcg/day post-workout',freq:'Once daily post-exercise never pre-sleep',hl:'~20–30 hours',hlh:25,admin:'SubQ · IM near target muscle',store:'Refrigerate 2–8C. Do not freeze. Use within 30 days.',recon:'Add bacteriostatic water or dilute acetic acid 0.6%. Handle gently.',bens:['Muscle cell hyperplasia new fibers','Enhanced protein synthesis via mTOR','Improved nutrient uptake','Dramatically accelerated recovery','Potentially permanent structural gains'],sides:['Hypoglycemia risk eat after dosing','Acromegalic features chronic high dose','Potential organ growth prolonged use','Insulin resistance','Never pre-sleep'],status:'Preclinical',pop:76,rel:['mgf','hexarelin','igf1des','pegmgf','follistatin344','ace031']},
  {id:'mgf',n:'MGF',fn:'Mechano Growth Factor (IGF-1Ec)',cat:'muscle',ov:'Splice variant of IGF-1 produced locally in muscle in response to mechanical loading or damage. The unique C-terminal E-peptide activates muscle satellite cells critical for hypertrophy.',mech:'The MGF E-peptide activates quiescent muscle stem cells independently of IGF-1 receptor, triggering their proliferation and fusion for repair and new fiber formation.',dose:'100–200 mcg, 2–3x weekly (pegylated preferred)',freq:'Post-workout 2–3x weekly',hl:'Minutes native; ~3 days PEG form',hlh:0.08,admin:'SubQ · IM',store:'Refrigerate reconstituted. PEG form more stable.',recon:'Add sterile/bacteriostatic water. Native: use immediately. PEG: stable weeks.',bens:['Satellite cell activation','Enhanced hypertrophy signaling','Local muscle repair and regeneration','Synergistic with IGF-1 LR3','Recovery from mechanical damage'],sides:['Very limited human safety data','Potential hypoglycemic effect','Unknown long-term risks'],status:'Preclinical',pop:48,rel:['igf1lr3','pegmgf']},
  {id:'epithalon',n:'Epithalon',fn:'Epitalon Tetrapeptide (Ala-Glu-Asp-Gly)',cat:'longevity',ov:'Tetrapeptide derived from pineal gland extract epitalamin, studied 35+ years by Russian gerontologist Vladimir Khavinson. The most compelling telomere-extending compound with documented anti-aging effects.',mech:'Activates telomerase enzyme promoting telomere elongation in somatic cells. Also regulates cortisol and melatonin production via the pineal gland with antioxidant and anti-tumor properties.',dose:'5–10 mg/day for 10–20 days, 1–2 cycles per year',freq:'Daily during cycle 10–20 days',hl:'Short ~2–4 hours',hlh:3,admin:'SubQ · IM · IV',store:'Lyophilized: room temp. Reconstituted: 2–8C.',recon:'Add 1–2 ml bacteriostatic water per vial.',bens:['Telomere elongation in aged cells','Circadian rhythm normalization','Antioxidant enzyme upregulation','Potential anti-tumor activity','Immune system restoration'],sides:['Exceptionally well tolerated','Vivid dreams some users','Minimal adverse events in 35 years'],status:'Preclinical (extensive Russian literature)',pop:66,rel:['ghkcu','thymalin','vilon','pinealon']},
  {id:'thymalin',n:'Thymalin',fn:'Thymalin Thymus Bioregulator Complex',cat:'longevity',ov:'Polypeptide fraction from bovine thymus gland. Long-term Russian clinical research demonstrates significant reduction in all-cause mortality and reversal of immunosenescence markers.',mech:'Restores thymic function and T-cell maturation, normalizes T-cell/B-cell ratios, improves natural killer cell activity, and counteracts age-related thymic involution.',dose:'10 mg/day for 10 days, 1–2 cycles per year',freq:'10-day course 1–2 cycles per year',hl:'Short',hlh:2,admin:'IM',store:'Refrigerate. Follow product handling instructions.',recon:'Reconstitute with sterile saline per manufacturer guidance.',bens:['Immune system restoration','Reduced infection susceptibility','T-cell and NK cell improvement','All-cause mortality reduction in studies','Biological age marker improvement'],sides:['Very well tolerated in decades of studies','Rare allergic reactions','Limited controlled data outside Russia'],status:'Approved (Russia/Eastern Europe)',pop:42,rel:['epithalon','thymogen','imunofan','vilon']},
  {id:'ss31',n:'SS-31',fn:'Elamipretide / MTP-131 (SS-31)',cat:'longevity',ov:'Mitochondria-targeted tetrapeptide selectively concentrating at the inner mitochondrial membrane. Restores mitochondrial function, bioenergetics, and structure. Currently in Phase III trials for heart failure.',mech:'Binds cardiolipin in the inner mitochondrial membrane, stabilizing structure, improving electron transport chain efficiency, reducing ROS production, and restoring optimal ATP output.',dose:'0.5–4 mg/day research; 40 mg IV clinical',freq:'Once daily SubQ',hl:'~2–3 hours',hlh:2.5,admin:'SubQ · IV',store:'Refrigerate. Sensitive to heat and light. Use promptly after reconstitution.',recon:'Reconstitute with sterile water carefully.',bens:['Mitochondrial function restoration','ROS and oxidative stress reduction','Improved ATP production','Heart and kidney protection','Muscle performance in aging'],sides:['Injection site reactions','Nausea occasional','Limited long-term data outside trials'],status:'Clinical (Phase II/III)',pop:52,rel:['epithalon','gdf11','foxo4dri','klotho']},
  {id:'dsip',n:'DSIP',fn:'Delta Sleep-Inducing Peptide',cat:'sleep',ov:'Naturally occurring nonapeptide found throughout the brain and peripheral organs. Named for its ability to induce slow-wave delta sleep. Also has significant effects on stress response and GH pulse regulation.',mech:'Modulates GABA, opiate, and serotonin receptor systems to promote sleep. Decreases hypothalamic somatostatin, increasing endogenous GH secretion. Reduces cortisol stress response.',dose:'100–200 mcg pre-sleep',freq:'Once daily pre-sleep; cycled 5–10 nights on',hl:'~30 min native; effects persist hours',hlh:0.5,admin:'SubQ',store:'Refrigerate reconstituted. Prepare fresh when possible.',recon:'Reconstitute with bacteriostatic water immediately before use.',bens:['Slow-wave sleep induction','Cortisol and stress reduction','Natural GH pulse enhancement','No morning grogginess','Antioxidant properties'],sides:['Very limited side effect data','Vivid dreams','Potential rebound wakefulness','Not for nightly chronic use'],status:'Preclinical',pop:60,rel:['ipamorelin','selank']},
  {id:'semax',n:'Semax',fn:'Semax ACTH(4-10) Heptapeptide Analogue',cat:'cognitive',ov:'Synthetic heptapeptide analogue of ACTH(4-7)PGP developed by the Russian Academy of Sciences. Approved in Russia for neurological conditions. Used globally for cognitive enhancement, neuroprotection, and stroke recovery.',mech:'Dramatically increases BDNF, NGF, and CNTF expression. Enhances cholinergic transmission and activates dopamine and serotonin systems. Reduces oxidative neural damage.',dose:'300–600 mcg/day',freq:'Once or twice daily; 2–4 week cycles',hl:'Minutes; cognitive effects persist hours',hlh:0.08,admin:'Intranasal · SubQ',store:'Refrigerate nasal spray. Injectable: refrigerate.',recon:'Pre-mixed nasal spray available. Can reconstitute in sterile saline for injection.',bens:['BDNF elevation neuronal growth','Enhanced focus and memory formation','Neuroprotection in stroke/hypoxia','Reduced anxiety and stress','Accelerated cognitive recovery'],sides:['Mild stimulant-like effects','Occasional headache','Anxiety at high doses','Rare nasal irritation'],status:'Approved (Russia) / Preclinical (West)',pop:81,rel:['selank','dsip','noopept','cerebrolysin','cortexin']},
  {id:'selank',n:'Selank',fn:'Selank TP-7 Tuftsin Analogue',cat:'cognitive',ov:'Synthetic heptapeptide analogue of human tuftsin developed in Russia. Uniquely combines anxiolytic properties with cognitive enhancement — reducing anxiety without sedation while improving focus.',mech:'Stabilizes enkephalin metabolism and increases endorphin activity. Modulates GABA-A receptors without binding benzodiazepine sites. Upregulates IL-6 and BDNF. Zero dependence or tolerance.',dose:'250–500 mcg/day',freq:'Once or twice daily; use as needed or cycled',hl:'Minutes; effects 4–8 hours',hlh:0.08,admin:'Intranasal · SubQ',store:'Refrigerate nasal spray. Stable weeks under refrigeration.',recon:'Available as nasal spray concentrate. Can reconstitute in sterile saline.',bens:['Anxiety reduction without sedation','Cognitive clarity and processing speed','Mood stabilization','Zero dependence or withdrawal','Immune modulation via IL-6'],sides:['Mild nasal irritation intranasal','Slight sedation at high doses rare','Minimal adverse events in research'],status:'Approved (Russia) / Preclinical (West)',pop:76,rel:['semax','dsip','noopept']},
  {id:'dihexa',n:'Dihexa',fn:'Dihexa (PNB-0408)',cat:'cognitive',ov:'Novel synthetic peptide derived from angiotensin IV. Reportedly 7 orders of magnitude more potent than BDNF in promoting synaptogenesis. One of the most potent cognitive-enhancing compounds discovered. Exercise extreme caution.',mech:'Binds hepatocyte growth factor and its receptor c-Met with high affinity, activating synaptogenic signaling with extraordinary potency. Promotes dendritic spine growth and new synaptic connections.',dose:'10–50 mg topical; 1–5 mg SubQ — start extremely low',freq:'Several times per week at most',hl:'Unknown; lipophilic likely CNS accumulation',hlh:24,admin:'SubQ · Topical DMSO',store:'Refrigerate. Dissolves in DMSO for transdermal delivery.',recon:'Transdermal in DMSO. Injectable requires appropriate solvent. Extreme potency demands precision.',bens:['Synaptogenesis promotion','Cognitive function in neurodegeneration models','Learning and memory enhancement','Neuroplasticity support','Potential Alzheimers research tool'],sides:['Extremely limited human data','Irreversible effects possible at high doses','Unknown long-term risks','Very easy to overdose — extreme potency'],status:'Preclinical (very early)',pop:38,rel:['semax','selank']},
  {id:'pt141',n:'PT-141',fn:'Bremelanotide (PT-141)',cat:'research',ov:'Melanocortin receptor agonist FDA-approved as Vyleesi for hypoactive sexual desire disorder in premenopausal women. Acts centrally on the brain rather than the vascular system unlike PDE5 inhibitors.',mech:'Activates melanocortin receptors MC1R, MC3R, and MC4R in the CNS, specifically regions governing sexual motivation and arousal, independently of any vascular mechanism.',dose:'0.5–2 mg (FDA-approved: 1.75 mg)',freq:'As needed 45 min before activity; max 1x per 24h',hl:'~2.7 hours',hlh:2.7,admin:'SubQ · Intranasal',store:'Refrigerate reconstituted. Nasal spray: room temp.',recon:'Reconstitute with sterile/bacteriostatic water. Pre-filled autoinjectors available.',bens:['FDA-approved for female HSDD','Central brain-based arousal mechanism','Independent of vascular system','Effective in both sexes research','Rapid onset 45–60 min'],sides:['Nausea most common','Facial flushing','Transient blood pressure changes','Hyperpigmentation with chronic use','Fatigue'],status:'FDA Approved (Vyleesi)',pop:71,rel:['melanotan2','melanotan1','setmelanotide']},
  {id:'thymosin_a1',n:'Thymosin α1',fn:'Thymosin Alpha-1',cat:'immune',ov:'Naturally occurring polypeptide isolated from thymus tissue. Used clinically in multiple countries for potent immunomodulatory effects. Approved as Zadaxin in some countries for hepatitis and cancer adjuvant.',mech:'Activates T-cell differentiation and maturation, enhances dendritic cell function, upregulates Toll-like receptors, and promotes Th1 immune responses comprehensively.',dose:'1.6–3.2 mg SubQ, 2x weekly',freq:'Twice weekly',hl:'~2 hours',hlh:2,admin:'SubQ',store:'Refrigerate reconstituted. Dry: room temp.',recon:'Reconstitute with bacteriostatic water. Standard 1.6 mg/ml concentration.',bens:['Immune system enhancement','Anti-cancer immunomodulation','Antiviral activity hepatitis','Vaccine adjuvant potential','Autoimmune regulation'],sides:['Generally very well tolerated','Flu-like symptoms initially','Injection site reactions'],status:'Approved (multiple countries)',pop:55,rel:['thymalin','imunofan','thymogen']},
  {id:'nad',n:'NAD+',fn:'Nicotinamide Adenine Dinucleotide Precursor',cat:'longevity',ov:'Critical coenzyme in cellular energy metabolism that declines with age. NAD+ precursors and IV NAD+ therapy are widely used in peptide wellness protocols for profound anti-aging and mitochondrial effects.',mech:'Essential for sirtuin SIRT1-7 activity, key longevity enzymes. Supports DNA repair via PARP enzymes, drives oxidative phosphorylation in mitochondria, and regulates circadian rhythm gene expression.',dose:'500–1000 mg NMN/NR orally; 250–500 mg IV NAD+',freq:'Daily oral; IV weekly or monthly',hl:'Variable by precursor form',hlh:12,admin:'Oral (NMN/NR) · IV',store:'Cool dark dry environment. IV preparations: refrigerate.',recon:'IV preparations come ready-to-use from compounding pharmacies.',bens:['Mitochondrial energy restoration','Sirtuin activation longevity enzymes','DNA repair support','Circadian rhythm optimization','Cognitive enhancement'],sides:['Flushing NR form','Nausea at high doses IV','GI discomfort oral','Potential medication interactions'],status:'Research (supplements) / Clinical (IV)',pop:82,rel:['ss31','epithalon','klotho','gdf11']},
  {id:'ghrp2',n:'GHRP-2',fn:'Growth Hormone Releasing Peptide 2',cat:'gh',ov:'Second-generation GHRP with a strong GH release profile and moderate appetite stimulation — less than GHRP-6 but more than Ipamorelin. Offers a middle ground in terms of selectivity and potency.',mech:'Binds ghrelin receptors in the pituitary and hypothalamus. Stimulates strong GH release while also moderately elevating ghrelin, resulting in some appetite stimulation and modest cortisol/prolactin elevation.',dose:'100–300 mcg/dose',freq:'2-3x daily on empty stomach',hl:'~30 minutes',hlh:0.5,admin:'SubQ',store:'Refrigerate reconstituted. Dry: room temp.',recon:'Add 1–2 ml bacteriostatic water per vial.',bens:['Strong GH secretion','Moderate appetite stimulation','IGF-1 increase','Recovery support','Balanced selectivity vs other GHRPs'],sides:['Moderate appetite increase','Mild cortisol elevation','Water retention','Tingling sensation'],status:'Preclinical',pop:60,rel:['ipamorelin','ghrp6','hexarelin']},
  {id:'follistatin344',n:'Follistatin 344',fn:'Follistatin 344 — Myostatin Inhibitor',cat:'muscle',ov:'Naturally occurring glycoprotein acting as a potent antagonist of myostatin, the primary brake on muscle growth. Blocking myostatin allows for muscle growth potential beyond normal genetic limits — one of the most powerful research compounds discussed in muscle biology.',mech:'Binds and neutralizes myostatin (GDF-8) and related TGF-beta superfamily members, removing their inhibitory signal on muscle satellite cells and enabling dramatically increased fiber number and size.',dose:'100 mcg/day for 10–30 days (cycle)',freq:'Daily during cycle',hl:'~3–5 hours',hlh:4,admin:'IM',store:'Refrigerate. Sensitive to degradation — use promptly.',recon:'Reconstitute carefully with bacteriostatic water. Very potent — precise dosing essential.',bens:['Myostatin inhibition','Significant muscle growth potential','Muscle fiber hyperplasia','Strength gains','Secondary fat loss effects'],sides:['Potential permanent changes if overdosed','Organ enlargement risk at high doses','Very limited human safety data','Requires precise dosing discipline'],status:'Preclinical',pop:50,rel:['igf1lr3','mgf','ace031']},
  {id:'exenatide',n:'Exenatide',fn:'Exenatide (Byetta / Bydureon)',cat:'metabolic',ov:'Synthetic version of exendin-4, a peptide originally isolated from Gila monster saliva. The first GLP-1 receptor agonist ever approved (2005), paving the way for the entire GLP-1 drug class that followed.',mech:'Activates GLP-1 receptors, stimulating glucose-dependent insulin secretion, suppressing glucagon, and slowing gastric emptying. Shorter-acting than newer GLP-1 agonists.',dose:'5–10 mcg twice daily (Byetta) or 2 mg weekly (Bydureon extended-release)',freq:'Twice daily or once weekly depending on formulation',hl:'~2.4 hours (immediate-release)',hlh:2.4,admin:'SubQ',store:'Refrigerate pens. Do not freeze.',recon:'Pre-filled pharmaceutical pens.',bens:['Blood glucose regulation','Modest weight loss','Established long-term safety track record','First-in-class proof of concept for GLP-1 therapy'],sides:['Nausea (common, especially initially)','Injection site reactions','Rare pancreatitis risk','Less weight loss than newer agents'],status:'FDA Approved',pop:55,rel:['liraglutide','semaglutide']},
  {id:'dulaglutide',n:'Dulaglutide',fn:'Dulaglutide (Trulicity)',cat:'metabolic',ov:'Long-acting GLP-1 receptor agonist fused to a modified antibody fragment, extending its half-life to allow once-weekly dosing. Widely prescribed for type 2 diabetes.',mech:'Activates GLP-1 receptors similarly to other agonists; the Fc-fusion design slows clearance, giving a full week of steady receptor activation from a single injection.',dose:'0.75–4.5 mg once weekly',freq:'Once weekly',hl:'~5 days',hlh:120,admin:'SubQ (auto-injector pen)',store:'Refrigerate 2–8°C. Can be kept at room temp up to 14 days.',recon:'Pre-filled pharmaceutical auto-injector.',bens:['Once-weekly convenience','Blood glucose regulation','Cardiovascular risk reduction (REWIND trial)','Moderate weight loss'],sides:['Nausea and GI upset','Pancreatitis risk (rare)','Injection site nodules','Less weight loss than semaglutide/tirzepatide'],status:'FDA Approved',pop:62,rel:['semaglutide','liraglutide']},
  {id:'retatrutide',n:'Retatrutide',fn:'Retatrutide (LY3437943)',cat:'metabolic',ov:'Investigational triple hormone receptor agonist — activating GLP-1, GIP, and glucagon receptors simultaneously. Phase 3 trial data has shown the largest average weight reduction of any pharmaceutical agent tested to date.',mech:'Combines GLP-1/GIP incretin effects (appetite suppression, insulin sensitization) with glucagon receptor activation, which increases energy expenditure and hepatic fat oxidation — a mechanism distinct from GLP-1-only or dual agonists.',dose:'Up to 12 mg/week in trials (titrated)',freq:'Once weekly (investigational)',hl:'~6 days',hlh:144,admin:'SubQ (investigational)',store:'Refrigerate. Not yet commercially available.',recon:'Not applicable — investigational compound, trial-supplied only.',bens:['Largest reported weight loss in trials (over 24% body weight)','Triple-pathway metabolic activation','Improved liver fat and lipid markers','Potential best-in-class GLP-1 successor'],sides:['GI side effects similar to other GLP-1s','Long-term safety data still being gathered','Not yet FDA approved','Limited real-world availability'],status:'Phase III (investigational)',pop:70,rel:['tirzepatide','semaglutide','survodutide']},
  {id:'cagrilintide',n:'Cagrilintide',fn:'Cagrilintide',cat:'metabolic',ov:'Long-acting amylin analogue developed by Novo Nordisk, often studied in combination with semaglutide (as "CagriSema"). Amylin is a satiety hormone co-secreted with insulin, working through a complementary pathway to GLP-1.',mech:'Activates amylin receptors in the brainstem and hypothalamus, slowing gastric emptying and enhancing satiety through a mechanism distinct from — and additive to — GLP-1 receptor activation.',dose:'Up to 4.5 mg/week in trials',freq:'Once weekly (investigational, often paired with semaglutide)',hl:'~7 days',hlh:168,admin:'SubQ (investigational)',store:'Refrigerate. Not yet commercially available as standalone.',recon:'Not applicable — investigational, trial-supplied only.',bens:['Complementary satiety mechanism to GLP-1','Enhanced weight loss when combined with semaglutide','Once-weekly dosing potential','Distinct receptor pathway may help those plateauing on GLP-1 alone'],sides:['GI side effects (nausea)','Limited standalone safety data','Not yet FDA approved','Primarily studied in combination, not alone'],status:'Phase III (investigational)',pop:58,rel:['semaglutide','retatrutide','pramlintide']},
  {id:'survodutide',n:'Survodutide',fn:'Survodutide (BI 456906)',cat:'metabolic',ov:'Dual glucagon/GLP-1 receptor agonist developed by Boehringer Ingelheim, in Phase 3 trials for obesity and MASH (metabolic dysfunction-associated steatohepatitis).',mech:'Combines GLP-1-driven appetite suppression with glucagon receptor activation, which increases hepatic fat oxidation and energy expenditure — particularly relevant for liver fat reduction.',dose:'Up to 6 mg/week in trials',freq:'Once weekly (investigational)',hl:'~5–6 days',hlh:132,admin:'SubQ (investigational)',store:'Refrigerate. Not yet commercially available.',recon:'Not applicable — investigational, trial-supplied only.',bens:['Significant weight loss in trials','Notable liver fat reduction (MASH focus)','Dual-pathway metabolic activation','Potential once-weekly dosing'],sides:['GI side effects typical of the class','Long-term safety still being established','Not yet FDA approved'],status:'Phase III (investigational)',pop:48,rel:['retatrutide','tirzepatide']},
  {id:'melanotan2',n:'Melanotan II',fn:'Melanotan II (MT-2)',cat:'research',ov:'Synthetic analogue of alpha-MSH originally developed for sunless tanning and photoprotection research. Became widely known for its pronounced effects on skin pigmentation and libido, though it was never approved as a pharmaceutical.',mech:'Non-selectively activates melanocortin receptors (MC1R for pigmentation, MC3R/MC4R for appetite and sexual arousal), stimulating melanin production and central arousal pathways simultaneously.',dose:'0.25–1 mg/day during loading, then 2–3x weekly maintenance',freq:'Daily loading, then maintenance dosing',hl:'~2–3 hours',hlh:2.5,admin:'SubQ',store:'Refrigerate reconstituted. Use within 4 weeks.',recon:'Add 1–2 ml bacteriostatic water per vial.',bens:['Increased melanin production (tanning)','Libido enhancement','Appetite suppression (secondary effect)','Photoprotective potential'],sides:['Nausea (very common, especially early doses)','Facial flushing','Spontaneous erections','Darkening of moles — dermatologist monitoring advised','Non-selective receptor activation increases side effect burden vs PT-141'],status:'Preclinical (never pharmaceutically approved)',pop:64,rel:['pt141','melanotan1']},
  {id:'melanotan1',n:'Melanotan I',fn:'Melanotan I (Afamelanotide)',cat:'research',ov:'The more selective predecessor to Melanotan II, targeting MC1R with greater specificity for pigmentation and less impact on libido/appetite pathways. Its pharmaceutical form, Afamelanotide (Scenesse), is FDA-approved for erythropoietic protoporphyria, a rare light-sensitivity disorder.',mech:'Selectively activates MC1R on melanocytes, stimulating eumelanin production and providing photoprotection without the broader MC3R/MC4R activation seen with Melanotan II.',dose:'1 mg implant every 2 months (pharmaceutical); research doses vary',freq:'Pharmaceutical: bi-monthly implant. Research use varies.',hl:'~2 hours (varies by formulation)',hlh:2,admin:'SubQ implant (pharmaceutical) · SubQ injection (research)',store:'Refrigerate. Follow product-specific handling.',recon:'Pharmaceutical implant requires no reconstitution; research vials use standard bacteriostatic water.',bens:['FDA-approved for erythropoietic protoporphyria','More selective than Melanotan II','Photoprotective effects','Fewer libido/appetite side effects than MT-2'],sides:['Nausea (less common than MT-2)','Injection site reactions','Skin darkening','Limited data outside approved indication'],status:'FDA Approved (as Afamelanotide, limited indication)',pop:40,rel:['melanotan2','pt141']},
  {id:'setmelanotide',n:'Setmelanotide',fn:'Setmelanotide (Imcivree)',cat:'research',ov:'FDA-approved MC4R agonist for chronic weight management in people with specific genetic obesity disorders (POMC, PCSK1, or LEPR deficiency). Represents precision medicine within the melanocortin pathway.',mech:'Selectively activates MC4R in the hypothalamus, restoring the appetite-suppressing signal that is disrupted in these specific genetic conditions.',dose:'Titrated to 3 mg/day (genetically-indicated patients)',freq:'Once daily',hl:'~11 hours',hlh:11,admin:'SubQ',store:'Refrigerate pre-filled pens.',recon:'Pre-filled pharmaceutical pen — no reconstitution.',bens:['FDA-approved for specific genetic obesity disorders','Significant weight loss in indicated populations','Reduces hunger scores substantially in trials','Targeted precision-medicine mechanism'],sides:['Injection site reactions','Nausea','Skin hyperpigmentation (MC1R crossover effect)','Only indicated for specific genetic conditions — not general weight loss'],status:'FDA Approved (limited genetic indication)',pop:35,rel:['melanotan2','pt141']},
  {id:'oxytocin',n:'Oxytocin',fn:'Oxytocin',cat:'reproductive',ov:'A naturally occurring neuropeptide hormone, often called the "bonding hormone," produced in the hypothalamus. Clinically used to induce labor and control postpartum bleeding, and widely studied in social/behavioral research for its role in trust, attachment, and stress regulation.',mech:'Binds oxytocin receptors throughout the brain (particularly the amygdala and nucleus accumbens) and uterus, modulating social cognition, stress response, and — peripherally — uterine contraction and milk ejection.',dose:'Clinical: 10–40 IU IV (labor). Research/intranasal: 24–40 IU',freq:'Situational — clinical use is procedure-specific; research use varies',hl:'~3–5 minutes (IV); longer with intranasal',hlh:0.08,admin:'IV (clinical) · Intranasal (research)',store:'Refrigerate. Protect from light.',recon:'Clinical formulations are pre-mixed; research nasal sprays come pre-formulated.',bens:['Established obstetric use (labor induction)','Studied for social bonding and trust','Stress and anxiety reduction in research settings','Well-characterized safety profile in clinical contexts'],sides:['Uterine hyperstimulation risk (clinical, high dose)','Water intoxication risk with excessive dosing','Headache','Nausea'],status:'FDA Approved (obstetric use) / Ongoing research (behavioral)',pop:45,rel:['kisspeptin10','gonadorelin']},
  {id:'kisspeptin10',n:'Kisspeptin-10',fn:'Kisspeptin-10',cat:'reproductive',ov:'A fragment of the kisspeptin protein, a master regulator of the reproductive hormone axis. Sits upstream of GnRH release, making it a key research target for fertility treatment and reproductive endocrinology.',mech:'Binds the kisspeptin receptor (KISS1R) on GnRH neurons, triggering a robust, physiological pulse of GnRH — and downstream LH and FSH release — making it of particular interest for fertility treatments that rely on natural hormonal pulsing.',dose:'Research doses vary (typically mcg-range, IV in clinical trials)',freq:'Situational — primarily studied in clinical fertility research settings',hl:'~28 minutes (IV)',hlh:0.47,admin:'IV · SubQ (research)',store:'Refrigerate reconstituted.',recon:'Add sterile water per research protocol.',bens:['Triggers physiological GnRH pulse','Fertility treatment research applications','Potential alternative to hCG trigger shots in IVF research','Studied for hypothalamic amenorrhea'],sides:['Very limited outside clinical trial settings','Headache','Flushing','Injection site reactions'],status:'Clinical trials (fertility research)',pop:30,rel:['oxytocin']},
  {id:'tabimorelin',n:'Tabimorelin',fn:'Tabimorelin',cat:'gh',ov:'An oral, non-peptide GH secretagogue candidate developed as an alternative to injectable GHRPs. Development was ultimately discontinued, but it remains referenced in GH secretagogue research literature.',mech:'Activates the ghrelin receptor (GHS-R1a) similarly to injectable GHRPs, but formulated for oral bioavailability rather than subcutaneous delivery.',dose:'Discontinued — historical trial doses were in the mg range orally',freq:'Was studied as once-daily oral dosing',hl:'Several hours (oral)',hlh:4,admin:'Oral (historical, discontinued)',store:'Not commercially available.',recon:'Not applicable — oral tablet, never commercialized.',bens:['Demonstrated oral GH secretagogue feasibility','Avoided injection requirement','Contributed to understanding of ghrelin receptor pharmacology'],sides:['Development discontinued (reasons not fully public)','No modern safety data','Not available for research or clinical use'],status:'Discontinued development',pop:15,rel:['mk677','ipamorelin']},
  {id:'alexamorelin',n:'Alexamorelin',fn:'Alexamorelin',cat:'gh',ov:'A GHRP analogue studied primarily in rodent models for its effects on memory and cognition alongside typical GH-releasing activity, making it a notable crossover compound between the GH and cognitive research categories.',mech:'Activates the ghrelin receptor like other GHRPs, stimulating GH release, with rodent studies suggesting additional effects on hippocampal memory consolidation possibly related to ghrelin\'s known role in the brain.',dose:'Primarily studied in animal models — no established human research dose',freq:'Not established for human use',hl:'Not well characterized in humans',hlh:1,admin:'SubQ (research/animal studies)',store:'Refrigerate reconstituted per general peptide handling.',recon:'Add bacteriostatic water per standard peptide reconstitution.',bens:['GH secretagogue activity','Rodent studies suggest memory/cognitive effects','Contributes to understanding of ghrelin\'s CNS role'],sides:['Very limited human data','Primarily an animal research compound','Not well characterized for human use'],status:'Preclinical (animal studies)',pop:20,rel:['ipamorelin','ghrp6']},
  {id:'pegmgf',n:'PEG-MGF',fn:'Pegylated Mechano Growth Factor',cat:'muscle',ov:'A polyethylene-glycol (PEG) modified version of MGF, engineered to resist rapid degradation. While native MGF breaks down in minutes, the pegylated form extends activity to several days, changing how it is used in research protocols.',mech:'Same satellite-cell activation mechanism as native MGF, but the PEG modification shields the peptide from enzymatic breakdown, extending systemic presence and allowing less frequent dosing.',dose:'200 mcg 1–2x weekly (differs from native MGF dosing due to extended half-life)',freq:'Once or twice weekly (vs. post-workout dosing for native MGF)',hl:'~2–3 days (vs. minutes for native MGF)',hlh:60,admin:'SubQ · IM',store:'Refrigerate reconstituted — notably more stable than native MGF.',recon:'Add bacteriostatic water per vial. More forgiving handling than native MGF due to PEG stability.',bens:['Extended half-life vs native MGF','Less frequent dosing required','Satellite cell activation','More stable/practical research handling'],sides:['Very limited long-term human data','Unknown immunogenicity of PEG component over time','Shares underlying MGF risk profile'],status:'Preclinical',pop:38,rel:['mgf','igf1lr3']},
  {id:'igf1des',n:'IGF-1 DES',fn:'Des(1-3) IGF-1',cat:'muscle',ov:'A truncated variant of IGF-1 missing the first three N-terminal amino acids. This modification reduces binding to IGF-binding proteins, making it significantly more potent (though shorter acting) than IGF-1 LR3.',mech:'Binds the IGF-1 receptor directly, activating the same PI3K/Akt/mTOR growth pathway as IGF-1 LR3, but with less buffering from binding proteins — producing a more intense but shorter window of activity.',dose:'40–120 mcg post-workout, localized to trained muscle',freq:'Once daily post-exercise, short cycles',hl:'~20–30 minutes (much shorter than LR3)',hlh:0.42,admin:'SubQ · IM (localized)',store:'Refrigerate 2–8°C. Do not freeze. Very short window once reconstituted.',recon:'Add bacteriostatic water or dilute acetic acid immediately before use — short stability window.',bens:['More potent receptor binding than IGF-1 LR3','Intense localized muscle growth signal','Useful for site-specific research protocols'],sides:['Significant hypoglycemia risk (more acute than LR3)','Very short window demands precise timing','Requires more frequent dosing than LR3','Same long-term risk profile as other IGF-1 analogues'],status:'Preclinical',pop:42,rel:['igf1lr3','mgf']},
  {id:'noopept',n:'Noopept',fn:'Noopept (GVS-111)',cat:'cognitive',ov:'A dipeptide-derived nootropic (ethyl ester of cycloprolylglycine) developed in Russia. One of the most widely recognized nootropic compounds in the research community due to its oral bioavailability and rapid onset.',mech:'Believed to modulate AMPA and NMDA glutamate receptors and increase BDNF and NGF expression, supporting synaptic plasticity, memory consolidation, and neuroprotection.',dose:'10–30 mg, 1–3x daily',freq:'Once to three times daily, oral',hl:'~1 hour (rapidly metabolized, effects reported to last longer)',hlh:1,admin:'Oral (sublingual absorption is fast)',store:'Room temperature, dry, dark container.',recon:'No reconstitution needed — oral capsule or powder.',bens:['Rapid onset (unlike many nootropics)','Reported memory and focus improvements','Neuroprotective properties in research','Oral administration — no injection needed'],sides:['Irritability at high doses (uncommon)','Headache','Sleep disturbance if taken late in the day','Long-term human safety data still limited'],status:'Approved (Russia) / Supplement status (elsewhere)',pop:58,rel:['semax','selank']},
  {id:'cerebrolysin',n:'Cerebrolysin',fn:'Cerebrolysin',cat:'cognitive',ov:'A mixture of low-molecular-weight peptides derived from purified pig brain proteins, used clinically in several countries for stroke recovery and cognitive decline. Distinct from single-molecule peptides due to its complex, multi-peptide composition.',mech:'Contains neurotrophic-like peptide fragments believed to mimic the action of BDNF, NGF, and other growth factors, supporting neuronal survival, reducing inflammation, and promoting synaptic repair after brain injury.',dose:'5–30 ml IV, typically in courses of 10–20 daily infusions',freq:'Daily infusion during treatment courses, followed by rest periods',hl:'Not well characterized (complex peptide mixture)',hlh:2,admin:'IV · IM (clinical)',store:'Refrigerate ampoules; protect from light.',recon:'Supplied as ready-to-use ampoules for clinical infusion.',bens:['Used clinically for stroke recovery in several countries','Studied for cognitive decline and traumatic brain injury','Neurotrophic-like properties from its peptide fraction blend','Decades of clinical use outside the US'],sides:['Not FDA approved in the United States','Injection site reactions','Rare allergic-type reactions','Requires clinical administration (IV infusion)'],status:'Approved (multiple countries, not US) / Clinical use',pop:44,rel:['semax','noopept']},
  {id:'cortexin',n:'Cortexin',fn:'Cortexin',cat:'cognitive',ov:'A polypeptide bioregulator derived from cattle or pig brain cortex tissue, part of the same Russian "Khavinson peptide" research tradition as Epithalon and Thymalin — but targeted at cognitive and neurological support rather than longevity or immunity.',mech:'Believed to normalize neuronal metabolism and support the brain\'s bioelectrical activity, with proposed neuroprotective and nootropic effects, though the exact molecular mechanism remains less defined than single-sequence peptides.',dose:'10 mg/day IM for 10 days (standard protocol)',freq:'10-day course, may be repeated periodically',hl:'Not well characterized',hlh:2,admin:'IM',store:'Refrigerate. Follow manufacturer-specific handling.',recon:'Reconstitute with sterile saline or water for injection per product instructions.',bens:['Used in Russian/Eastern European clinical settings for cognitive support','Part of the well-studied Khavinson bioregulator peptide family','Proposed neuroprotective properties','Long history of use in its home markets'],sides:['Limited data outside Russian/Eastern European literature','Not FDA approved','Injection site reactions'],status:'Approved (Russia/Eastern Europe)',pop:28,rel:['pinealon','epithalon']},
  {id:'pinealon',n:'Pinealon',fn:'Pinealon',cat:'cognitive',ov:'A short synthetic tripeptide from the same Khavinson bioregulator research tradition as Epithalon, but specifically studied for its effects on the brain and pineal gland rather than systemic longevity.',mech:'Proposed to regulate gene expression related to neuronal protein synthesis and antioxidant defense in brain tissue, with animal studies suggesting improved cognitive function and stress resilience in aging models.',dose:'10 mg/day for 10 days (research protocol, based on Khavinson bioregulator dosing pattern)',freq:'10-day course, periodic repetition',hl:'Short, not precisely characterized',hlh:2,admin:'Intranasal · SubQ (research)',store:'Refrigerate reconstituted.',recon:'Add bacteriostatic water per vial.',bens:['Studied for cognitive support in aging models','Part of the Khavinson short-peptide bioregulator family','Proposed antioxidant effects in brain tissue'],sides:['Very limited data outside Russian research literature','Not FDA approved','Long-term human safety not well established'],status:'Preclinical (Russian literature)',pop:22,rel:['cortexin','epithalon']},
  {id:'vilon',n:'Vilon',fn:'Vilon (Lys-Glu Dipeptide)',cat:'longevity',ov:'One of the simplest bioregulator peptides in the Khavinson family — just two amino acids (lysine-glutamic acid). Studied for immune and thymic restoration effects similar to Thymalin, but with a much shorter, simpler structure.',mech:'Proposed to activate gene expression related to protein synthesis in immune cells and thymic tissue, supporting immune function restoration in aging models, similar in concept to Thymalin but structurally distinct.',dose:'10 mg/day for 10 days (Khavinson protocol pattern)',freq:'10-day course, periodic repetition (1–2x per year)',hl:'Short, not precisely characterized',hlh:2,admin:'SubQ · IM',store:'Refrigerate. Follow product-specific instructions.',recon:'Reconstitute with bacteriostatic water per vial.',bens:['Simplest peptide in the Khavinson bioregulator family','Studied for immune and thymic support','Proposed anti-aging effects in Russian literature'],sides:['Very limited data outside Russian research','Not FDA approved','Long-term safety not well established outside its home literature'],status:'Preclinical (Russian literature)',pop:18,rel:['thymalin','epithalon']},
  {id:'thymogen',n:'Thymogen',fn:'Thymogen (Glu-Trp Dipeptide)',cat:'immune',ov:'A synthetic dipeptide (glutamine-tryptophan) studied as an immunomodulator, closely related in concept to Thymalin but structurally simpler — part of the broader family of thymus-derived Russian bioregulator peptides.',mech:'Proposed to stimulate T-lymphocyte differentiation and normalize immune cell ratios, similar in intent to Thymalin, believed to act on immune cell gene expression to restore function in immunocompromised or aging states.',dose:'100 mcg/day IM for 3–10 days (varies by protocol)',freq:'Short course, may be repeated periodically',hl:'Short, not precisely characterized',hlh:2,admin:'IM · Intranasal',store:'Refrigerate. Follow product-specific instructions.',recon:'Reconstitute with sterile saline per protocol.',bens:['Studied for immune system modulation','Simple two-amino-acid structure','Part of the established Russian thymic bioregulator research tradition'],sides:['Limited data outside Russian/Eastern European literature','Not FDA approved','Injection site reactions'],status:'Approved (Russia/Eastern Europe)',pop:24,rel:['thymalin','imunofan']},
  {id:'imunofan',n:'Imunofan',fn:'Imunofan (Arg-Glu-Asp-Lys-Val-Tyr-Arg)',cat:'immune',ov:'A synthetic hexapeptide immunomodulator developed in Russia, studied for its ability to normalize immune function, reduce oxidative stress, and support recovery from chronic infections — distinct from the simpler Khavinson dipeptides due to its longer sequence and broader documented clinical use.',mech:'Proposed to normalize the balance of pro- and anti-inflammatory cytokines, stimulate antibody production during active infection, and act as a direct antioxidant by neutralizing free radicals independent of immune signaling.',dose:'1 ml (50 mcg) IM, every other day for 10–15 injections',freq:'Every other day for a defined course',hl:'Not well characterized',hlh:2,admin:'IM · Intranasal',store:'Refrigerate ampoules.',recon:'Supplied as pre-mixed ampoules for clinical use in its home markets.',bens:['Studied for chronic infection recovery support','Antioxidant properties independent of immune effects','Used clinically in Russia for various immune-related conditions','More extensive documented use than simpler bioregulator dipeptides'],sides:['Not FDA approved','Limited data outside Russian/Eastern European clinical literature','Injection site reactions'],status:'Approved (Russia)',pop:26,rel:['thymogen','thymalin']},
  {id:'ara290',n:'ARA-290',fn:'ARA-290 (Cibinetide)',cat:'healing',ov:'A synthetic peptide derived from erythropoietin (EPO), engineered to retain EPO\'s tissue-protective effects while removing its blood-cell-stimulating activity — avoiding the cardiovascular risks associated with EPO itself.',mech:'Selectively activates the "innate repair receptor," a complex distinct from the classical EPO receptor, triggering anti-inflammatory and cytoprotective signaling in nerve and vascular tissue without affecting red blood cell production.',dose:'Studied at 4–16 mg SubQ in clinical trials',freq:'Varies by trial protocol — often several times weekly',hl:'~28 minutes',hlh:0.47,admin:'SubQ',store:'Refrigerate reconstituted per trial protocol.',recon:'Reconstitute with sterile water per research protocol.',bens:['Tissue-protective effects without EPO\'s blood-thickening risk','Studied for diabetic neuropathy pain relief','Anti-inflammatory properties','Vascular protective effects in trials'],sides:['Limited to clinical trial settings','Long-term safety still being established','Not yet FDA approved for any indication'],status:'Clinical trials (Phase II)',pop:20,rel:['bpc157','ll37']},
  {id:'larazotide',n:'Larazotide Acetate',fn:'Larazotide Acetate (AT-1001)',cat:'healing',ov:'A synthetic octapeptide developed as a "zonulin antagonist" — targeting the protein responsible for regulating tight junction permeability in the gut lining. Studied primarily as an adjunct treatment for celiac disease.',mech:'Blocks zonulin-mediated opening of intestinal tight junctions, reducing gut permeability ("leaky gut") and limiting the passage of gluten fragments that trigger immune reactions in celiac disease.',dose:'0.5–3 mg orally before meals (clinical trial dosing)',freq:'Before each meal (up to 3x daily in trials)',hl:'Minimal systemic absorption — acts locally in the gut',hlh:1,admin:'Oral',store:'Room temperature, per trial formulation.',recon:'Oral capsule — no reconstitution needed.',bens:['Targets gut permeability directly (zonulin pathway)','Studied specifically for celiac disease symptom control','Oral administration — no injection required','Minimal systemic absorption reduces off-target risk'],sides:['Headache (most common in trials)','GI discomfort','Not yet FDA approved','Effectiveness varies across trial results'],status:'Clinical trials (Phase III)',pop:18,rel:['bpc157','kpv']},
  {id:'foxo4dri',n:'FOXO4-DRI',fn:'FOXO4-DRI (D-Retro-Inverso Peptide)',cat:'longevity',ov:'A designed peptide that disrupts the interaction between FOXO4 and p53 inside senescent ("zombie") cells, causing these cells to undergo apoptosis. First described in a landmark 2017 study, it represents a distinct senolytic approach compared to small-molecule senolytics.',mech:'Interferes with the FOXO4-p53 protein-protein interaction specifically within senescent cells, releasing p53 to trigger programmed cell death selectively in these dysfunctional, pro-inflammatory cells while sparing healthy tissue.',dose:'Animal studies used ~5–10 mg/kg — no established human dose',freq:'Not established for human use',hl:'Not well characterized in humans',hlh:4,admin:'IP (animal studies) — human route not established',store:'Refrigerate/freeze per research-grade handling.',recon:'Research-grade reconstitution varies — not standardized for human use.',bens:['Selectively targets senescent cells (senolytic mechanism)','Demonstrated rejuvenation effects in aged mice (fur density, kidney function, running endurance)','Distinct mechanism from small-molecule senolytics like dasatinib/quercetin'],sides:['No established human safety data','Animal-stage research only','Selective cell-killing mechanisms carry theoretical off-target risk'],status:'Preclinical (animal studies)',pop:34,rel:['gdf11','klotho']},
  {id:'gdf11',n:'GDF11',fn:'Growth Differentiation Factor 11',cat:'longevity',ov:'A circulating protein studied in controversial "young blood" parabiosis research, where blood from young mice was shown to rejuvenate muscle and cardiac tissue in older mice. GDF11 was proposed as a key rejuvenating factor, though subsequent studies have produced conflicting results.',mech:'A member of the TGF-beta superfamily, proposed to signal through Smad2/3 pathways to influence muscle stem cell function and cardiac tissue remodeling, though its precise role remains scientifically contested.',dose:'Not established for human use — research remains at the animal/mechanistic stage',freq:'Not established',hl:'Not well characterized',hlh:1,admin:'Not established for human research use',store:'Research-grade cold chain handling.',recon:'Not standardized — laboratory research use only.',bens:['Proposed muscle and cardiac rejuvenation in early animal studies','Central to influential (though contested) "young blood" aging research','Active area of ongoing longevity science debate'],sides:['Conflicting research results — some studies suggest it may worsen rather than improve aging phenotypes','No human safety data','Highly experimental, mechanism not fully resolved'],status:'Preclinical (contested research findings)',pop:26,rel:['foxo4dri','klotho']},
  {id:'klotho',n:'Klotho',fn:'Klotho (α-Klotho Protein)',cat:'longevity',ov:'An anti-aging protein named after the Greek Fate who spins the thread of life. Mice engineered to overexpress klotho show extended lifespan, while klotho-deficient mice show accelerated aging — making it one of the most studied single genes in aging biology.',mech:'Acts as both a membrane-bound co-receptor (regulating FGF23 signaling in kidney and phosphate metabolism) and a circulating hormone-like factor with proposed effects on insulin sensitivity, oxidative stress resistance, and cognitive function.',dose:'Not established for human use — research remains at the animal/mechanistic stage',freq:'Not established',hl:'Not well characterized',hlh:1,admin:'Not established for human research use',store:'Research-grade cold chain handling.',recon:'Not standardized — laboratory research use only.',bens:['Strongly linked to lifespan extension in animal models','Proposed cognitive and cardiovascular protective effects','One of the most robustly studied longevity-associated proteins'],sides:['No human dosing or safety data established','Purely mechanistic/animal-stage research currently','Not available in any injectable research form with established quality control'],status:'Preclinical (mechanistic/animal research)',pop:32,rel:['gdf11','foxo4dri']},
  {id:'adipotide',n:'Adipotide',fn:'Adipotide (FTPP)',cat:'fatloss',ov:'An experimental peptide developed at a major cancer research center that selectively targets the blood supply of white adipose (fat) tissue, causing targeted fat cell death. Produced dramatic weight loss in primate studies, but development has been limited by kidney toxicity concerns.',mech:'Binds prohibitin, a protein found on blood vessels feeding white adipose tissue, and triggers localized apoptosis of those vessels — cutting off blood supply to fat tissue and causing the fat cells to die and be cleared, rather than simply shrink.',dose:'Primate studies used doses inducing 25–40% body weight loss over weeks — no established human protocol',freq:'Not established for human use',hl:'Not well characterized in humans',hlh:2,admin:'SubQ (primate research)',store:'Research-grade cold chain handling.',recon:'Not standardized for human use.',bens:['Dramatic fat loss demonstrated in primate studies','Novel vascular-targeting mechanism distinct from GLP-1 or GH pathways','Fat cell death rather than just shrinkage'],sides:['Kidney toxicity observed in primate studies — significant safety concern','No established human safety profile','Development has been limited specifically due to renal risk','Considered one of the higher-risk experimental compounds discussed in research circles'],status:'Preclinical (primate studies)',pop:30,rel:['aod9604','tesamorelin']},
  {id:'ace031',n:'ACE-031',fn:'ACE-031',cat:'muscle',ov:'A soluble activin receptor type IIB fusion protein designed to block myostatin and related growth inhibitors. Trialed for Duchenne muscular dystrophy before being discontinued due to vascular side effects.',mech:'Acts as a decoy receptor, binding and sequestering myostatin and activin before they can inhibit muscle growth signaling — conceptually similar to Follistatin but through a different receptor-trap mechanism.',dose:'Trial doses were in the mg/kg IV/SubQ range — discontinued, no current protocol',freq:'Was studied as periodic dosing in clinical trials',hl:'Days (fusion protein, longer-acting)',hlh:96,admin:'SubQ (historical clinical trials)',store:'Not commercially available.',recon:'Not applicable — discontinued development.',bens:['Demonstrated significant muscle mass increases in trials','Validated the activin/myostatin blocking approach in humans','Contributed to understanding of muscle growth inhibitor pathways'],sides:['Trial discontinued due to nosebleeds and vascular abnormalities (telangiectasia)','No longer in active development','No modern safety data or availability'],status:'Discontinued development (Phase II trials)',pop:20,rel:['follistatin344','igf1lr3']},
  {id:'argireline',n:'Argireline',fn:'Argireline (Acetyl Hexapeptide-8)',cat:'healing',ov:'A synthetic hexapeptide widely used in cosmetic formulations as a topical alternative to Botox. Works at the neuromuscular junction rather than through collagen stimulation, targeting expression lines caused by repeated muscle contraction.',mech:'Inhibits SNARE complex formation at the neuromuscular junction, reducing the release of neurotransmitters that trigger facial muscle contraction — softening the look of expression lines without paralyzing the muscle.',dose:'Topical: 5–10% concentration in serum/cream',freq:'Once or twice daily, topical application',hl:'Not applicable (topical, localized effect)',hlh:1,admin:'Topical',store:'Room temperature in sealed, light-protected container.',recon:'Pre-formulated in cosmetic serums — no reconstitution needed.',bens:['Reduces appearance of expression lines','Non-invasive alternative to injectable neuromodulators','Well-tolerated for topical cosmetic use','Widely used in commercial skincare formulations'],sides:['Mild skin irritation (uncommon)','Effects are subtle compared to injectable neuromodulators','Requires consistent long-term use for visible results'],status:'Cosmetic ingredient (widely available)',pop:36,rel:['snap8','matrixyl']},
  {id:'snap8',n:'SNAP-8',fn:'SNAP-8 (Acetyl Octapeptide-3)',cat:'healing',ov:'An extended version of Argireline\'s peptide sequence, marketed as a more potent topical anti-wrinkle ingredient with a similar neuromuscular mechanism but reportedly greater efficacy in cosmetic studies.',mech:'Also inhibits SNARE complex formation at the neuromuscular junction, similar to Argireline, but the longer peptide chain is reported to bind more effectively, producing a stronger reduction in muscle-contraction-driven wrinkles.',dose:'Topical: 3–10% concentration in serum/cream',freq:'Once or twice daily, topical application',hl:'Not applicable (topical, localized effect)',hlh:1,admin:'Topical',store:'Room temperature in sealed, light-protected container.',recon:'Pre-formulated in cosmetic serums — no reconstitution needed.',bens:['Reported greater potency than Argireline in cosmetic trials','Non-invasive topical application','Targets expression-line formation directly','Common in premium anti-aging skincare lines'],sides:['Mild skin irritation (uncommon)','Cosmetic-grade evidence rather than rigorous clinical trials','Effects are subtle and gradual'],status:'Cosmetic ingredient (widely available)',pop:28,rel:['argireline','matrixyl']},
  {id:'matrixyl',n:'Matrixyl',fn:'Matrixyl (Palmitoyl Pentapeptide-4)',cat:'healing',ov:'One of the most extensively used peptides in anti-aging skincare, combining a fatty acid chain with a signal peptide to enhance skin penetration and stimulate the skin\'s own repair matrix.',mech:'The palmitoyl group aids penetration through the skin barrier, while the peptide fragment signals fibroblasts to increase collagen, elastin, and glycosaminoglycan production — supporting the skin\'s structural matrix.',dose:'Topical: 3–8% concentration in serum/cream',freq:'Once or twice daily, topical application',hl:'Not applicable (topical, localized effect)',hlh:1,admin:'Topical',store:'Room temperature in sealed, light-protected container.',recon:'Pre-formulated in cosmetic serums — no reconstitution needed.',bens:['Stimulates collagen and elastin production','Improves skin firmness and texture over time','Extensively used and studied in commercial skincare','Well-tolerated for long-term topical use'],sides:['Mild irritation in sensitive skin (uncommon)','Results require weeks of consistent use to become visible','Effects are gradual, not immediate'],status:'Cosmetic ingredient (widely available)',pop:42,rel:['argireline','ghkcu']},
  {id:'ahkcu',n:'AHK-Cu',fn:'AHK-Cu (Alanine-Histidine-Lysine Copper Peptide)',cat:'healing',ov:'A copper-binding tripeptide related to GHK-Cu, studied specifically for its effects on hair follicle stimulation and scalp health, with a slightly different amino acid sequence than its better-known relative.',mech:'Similar to GHK-Cu, chelates copper and delivers it to tissue while activating genes related to tissue remodeling — with research emphasis specifically on hair follicle dermal papilla cell proliferation.',dose:'Topical: 0.1–1% concentration in scalp serum',freq:'Once daily, topical application to scalp',hl:'Not applicable (topical, localized effect)',hlh:1,admin:'Topical',store:'Room temperature in sealed, light-protected container.',recon:'Pre-formulated in cosmetic/scalp serums — no reconstitution needed.',bens:['Studied for hair follicle stimulation','Copper-delivery tissue remodeling effects','Topical application — no injection required','Complements GHK-Cu in some combination formulations'],sides:['Mild scalp irritation (uncommon)','Less extensively studied than GHK-Cu','Cosmetic-grade evidence base'],status:'Cosmetic/research ingredient',pop:20,rel:['ghkcu','matrixyl']},
  {id:'secretin',n:'Secretin',fn:'Secretin',cat:'research',ov:'One of the first peptide hormones ever discovered, secretin is produced by the small intestine and used clinically as a diagnostic agent to test pancreatic function and assist in imaging procedures.',mech:'Binds secretin receptors on pancreatic ductal cells, stimulating bicarbonate-rich fluid secretion — used diagnostically to assess pancreatic reserve and to aid visualization during endoscopic imaging.',dose:'0.2 mcg/kg IV (diagnostic dose)',freq:'Single diagnostic dose, as needed for testing',hl:'~3 minutes',hlh:0.05,admin:'IV (clinical)',store:'Refrigerate. Reconstitute immediately before diagnostic use.',recon:'Reconstitute with supplied diluent per diagnostic kit instructions.',bens:['Historic — one of the first hormones ever identified','FDA-approved for pancreatic function testing','Aids diagnostic imaging of the pancreas and bile ducts','Well-established clinical safety profile'],sides:['Flushing','Nausea','Abdominal discomfort','Rare hypersensitivity reactions'],status:'FDA Approved (diagnostic use)',pop:15,rel:['sincalide']},
  {id:'sincalide',n:'Sincalide',fn:'Sincalide (Cholecystokinin Analogue)',cat:'research',ov:'A synthetic fragment of cholecystokinin (CCK), the hormone responsible for gallbladder contraction and satiety signaling. Used clinically as a diagnostic agent to evaluate gallbladder function.',mech:'Activates CCK receptors on the gallbladder, triggering contraction — used diagnostically to measure gallbladder ejection fraction during nuclear medicine imaging studies.',dose:'0.02 mcg/kg IV over 30–60 minutes (diagnostic dose)',freq:'Single diagnostic dose, as needed for testing',hl:'~2–3 minutes',hlh:0.04,admin:'IV (clinical)',store:'Refrigerate. Reconstitute immediately before diagnostic use.',recon:'Reconstitute with sterile water per diagnostic kit instructions.',bens:['FDA-approved for gallbladder function testing','Well-characterized diagnostic use','Established safety profile in clinical imaging settings'],sides:['Abdominal cramping','Nausea','Diarrhea','Flushing'],status:'FDA Approved (diagnostic use)',pop:12,rel:['secretin']},
  {id:'corticorelin',n:'Corticorelin',fn:'Corticorelin (Acthrel)',cat:'research',ov:'A synthetic form of corticotropin-releasing hormone, used clinically to help distinguish between different causes of Cushing\'s syndrome by testing pituitary ACTH responsiveness.',mech:'Binds CRH receptors on the pituitary, stimulating ACTH release. The pattern and magnitude of the ACTH/cortisol response helps differentiate pituitary from adrenal or ectopic sources of excess cortisol.',dose:'1 mcg/kg IV (diagnostic dose)',freq:'Single diagnostic dose',hl:'~50 minutes',hlh:0.83,admin:'IV (clinical)',store:'Refrigerate. Reconstitute immediately before use.',recon:'Reconstitute with supplied diluent per diagnostic kit instructions.',bens:['FDA-approved diagnostic tool for Cushing\'s syndrome','Helps localize the source of excess cortisol production','Well-established clinical protocol'],sides:['Flushing','Mild blood pressure changes','Metallic taste','Rare hypersensitivity reactions'],status:'FDA Approved (diagnostic use)',pop:10,rel:['secretin','sincalide']},
  {id:'grf144',n:'GRF 1-44',fn:'Growth Hormone Releasing Factor (1-44)',cat:'gh',ov:'The full-length 44-amino-acid form of growth hormone releasing hormone, distinct from the shorter GHRH(1-29) fragment used in Sermorelin. Represents the complete natural sequence before it is enzymatically shortened in the body.',mech:'Binds GHRH receptors on pituitary somatotrophs identically to Sermorelin\'s mechanism, stimulating natural pulsatile GH release — the longer sequence is sometimes reported to have marginally different stability characteristics.',dose:'100–300 mcg/day',freq:'Once daily, pre-sleep',hl:'~7 minutes (rapidly cleaved in vivo)',hlh:0.12,admin:'SubQ',store:'Refrigerate reconstituted. Use within 30 days.',recon:'Add bacteriostatic water per vial, similar to Sermorelin handling.',bens:['Full natural GHRH sequence','Physiological pulsatile GH stimulation','Comparable mechanism and safety profile to Sermorelin'],sides:['Facial flushing','Injection site discomfort','Headache','Very short half-life requires precise timing'],status:'Preclinical',pop:18,rel:['sermorelin','cjc1295']},
  {id:'somatropin',n:'Somatropin',fn:'Somatropin (Recombinant Human Growth Hormone)',cat:'gh',ov:'Recombinant human growth hormone itself — the actual downstream hormone that every GH secretagogue on this platform is designed to stimulate the body into producing naturally. FDA-approved for diagnosed GH deficiency and several other specific conditions.',mech:'Directly binds GH receptors throughout the body, stimulating IGF-1 production in the liver and acting directly on bone, muscle, and fat tissue — bypassing the pituitary\'s natural regulatory feedback entirely, unlike secretagogues.',dose:'0.15–0.3 mg/day (adult GH deficiency, varies significantly by indication)',freq:'Once daily, typically evening',hl:'~3.8 hours',hlh:3.8,admin:'SubQ',store:'Refrigerate. Some formulations stable at room temperature for limited periods.',recon:'Pre-filled pens or vials reconstituted with supplied diluent.',bens:['FDA-approved for diagnosed GH deficiency','Directly restores GH levels without relying on pituitary response','Well-established clinical dosing protocols','Decades of pharmaceutical safety data'],sides:['Joint pain and swelling','Fluid retention','Carpal tunnel-like symptoms','Insulin resistance risk','Requires medical supervision due to bypassing natural feedback loops'],status:'FDA Approved',pop:56,rel:['ipamorelin','cjc1295','sermorelin']},
  {id:'gonadorelin',n:'Gonadorelin',fn:'Gonadorelin (GnRH)',cat:'reproductive',ov:'The synthetic form of naturally occurring gonadotropin-releasing hormone, sitting at the very top of the reproductive hormone cascade. Used clinically for diagnostic testing and fertility treatment, and commonly discussed in hormone therapy contexts for maintaining natural testicular function.',mech:'Binds GnRH receptors on the pituitary, stimulating pulsatile release of LH and FSH — the signals that drive testosterone production in the testes and estrogen/progesterone cycling in the ovaries.',dose:'100 mcg SubQ, 2-3x weekly (protocol-dependent)',freq:'Multiple times weekly, pulsatile dosing preferred',hl:'~10–40 minutes',hlh:0.4,admin:'SubQ',store:'Refrigerate reconstituted. Use within 30 days.',recon:'Add bacteriostatic water per vial.',bens:['Maintains natural LH/FSH signaling','Supports testicular function during hormone therapy protocols','Used diagnostically to assess pituitary-gonadal axis function','Short half-life allows pulsatile dosing that mimics natural physiology'],sides:['Headache','Flushing','Nausea','Injection site reactions','Requires frequent dosing due to short half-life'],status:'FDA Approved (diagnostic and therapeutic use)',pop:38,rel:['hcg','triptorelin']},
  {id:'triptorelin',n:'Triptorelin',fn:'Triptorelin (Decapeptyl / Trelstar)',cat:'reproductive',ov:'A long-acting GnRH agonist that, after initial stimulation, ultimately suppresses the pituitary-gonadal axis through receptor downregulation. FDA-approved for prostate cancer, endometriosis, and precocious puberty.',mech:'Initially stimulates GnRH receptors like natural GnRH, but continuous rather than pulsatile receptor activation causes desensitization — paradoxically suppressing LH/FSH and downstream sex hormone production after an initial flare.',dose:'3.75–22.5 mg depot injection, monthly to every 6 months depending on formulation',freq:'Monthly, quarterly, or semi-annual depot injection',hl:'~3 hours (active moiety); depot effect lasts months',hlh:3,admin:'IM (depot formulation)',store:'Refrigerate. Reconstitute per manufacturer kit instructions.',recon:'Supplied as pre-measured depot kits reconstituted with included diluent.',bens:['FDA-approved for prostate cancer and endometriosis','Long-acting depot formulation reduces dosing frequency','Well-established suppression of sex hormone production when needed'],sides:['Initial testosterone/estrogen flare before suppression','Hot flashes','Bone density loss with long-term use','Injection site reactions'],status:'FDA Approved',pop:24,rel:['leuprolide','gonadorelin']},
  {id:'leuprolide',n:'Leuprolide',fn:'Leuprolide (Lupron)',cat:'reproductive',ov:'One of the most widely recognized GnRH agonists, used extensively for prostate cancer, endometriosis, uterine fibroids, precocious puberty, and as part of fertility (IVF) protocols.',mech:'Like triptorelin, continuous GnRH receptor activation ultimately downregulates the receptor, suppressing LH/FSH and sex hormone production after an initial stimulatory phase — used therapeutically to create a controlled hormonal environment.',dose:'3.75–30 mg depot injection, monthly to every 6 months depending on formulation',freq:'Monthly or longer-acting depot injection',hl:'~3 hours (active moiety); depot effect lasts months',hlh:3,admin:'SubQ · IM (depot formulation)',store:'Refrigerate. Reconstitute per manufacturer kit instructions.',recon:'Supplied as pre-measured depot kits reconstituted with included diluent.',bens:['FDA-approved for prostate cancer, endometriosis, and fibroids','Extensively used in IVF fertility protocols','Long clinical track record across multiple indications'],sides:['Initial hormone flare before suppression','Hot flashes','Bone density loss with long-term use','Mood changes'],status:'FDA Approved',pop:30,rel:['triptorelin','gonadorelin']},
  {id:'hcg',n:'hCG',fn:'Human Chorionic Gonadotropin',cat:'reproductive',ov:'A hormone naturally produced during pregnancy, and pharmaceutically used to mimic LH signaling — stimulating testosterone production in men and supporting ovulation in fertility treatment for women.',mech:'Binds LH receptors (since hCG and LH share a nearly identical receptor-binding structure), directly stimulating Leydig cells in the testes to produce testosterone, or triggering ovulation in the ovaries.',dose:'250–1500 IU, 2-3x weekly (protocol-dependent)',freq:'Multiple times weekly',hl:'~24–36 hours',hlh:30,admin:'SubQ · IM',store:'Refrigerate reconstituted. Use within 60 days at 2-8°C.',recon:'Add bacteriostatic water per vial — standard concentration 1000-5000 IU/ml.',bens:['Maintains testicular size and function during hormone therapy','Triggers ovulation in fertility treatment protocols','Long clinical history and well-established dosing','Mimics natural LH signaling directly'],sides:['Water retention','Mood changes','Injection site reactions','Gynecomastia risk at high doses in men','Ovarian hyperstimulation risk in fertility protocols'],status:'FDA Approved',pop:52,rel:['gonadorelin','triptorelin']},
  {id:'thymosinbeta4',n:'Thymosin Beta-4',fn:'Thymosin Beta-4 (Full Length, Tβ4)',cat:'healing',ov:'The complete, naturally occurring 43-amino-acid protein from which TB-500 (a synthetic fragment) is derived. Present in nearly all human and animal cells, it is the original molecule underlying the healing effects associated with TB-500.',mech:'Sequesters G-actin monomers and regulates actin polymerization for cell migration, while also stimulating angiogenesis and modulating inflammation — the same core mechanisms attributed to TB-500, since TB-500 is designed to replicate this activity.',dose:'Research dosing generally mirrors TB-500 protocols',freq:'Similar to TB-500 dosing patterns',hl:'Short in circulation, but tissue effects persist',hlh:2,admin:'SubQ · IM',store:'Lyophilized: room temp. Reconstituted: refrigerate 2-8°C.',recon:'Add bacteriostatic water per vial, similar to TB-500 handling.',bens:['Original natural molecule behind TB-500\'s effects','Systemic tissue repair and anti-inflammatory action','Cell migration and angiogenesis support'],sides:['Similar profile to TB-500 — mild fatigue, occasional headache','Less commercially available than the TB-500 fragment','Sometimes used interchangeably with TB-500 in community discussion, though technically distinct'],status:'Preclinical',pop:34,rel:['tb500','bpc157']},
  {id:'pramlintide',n:'Pramlintide',fn:'Pramlintide (Symlin)',cat:'metabolic',ov:'A synthetic analogue of amylin, a hormone co-secreted with insulin that regulates satiety and gastric emptying. FDA-approved as an adjunct to insulin therapy for type 1 and type 2 diabetes, and the direct predecessor to newer long-acting amylin analogues like Cagrilintide.',mech:'Activates amylin receptors in the brainstem, slowing gastric emptying, suppressing glucagon secretion, and enhancing satiety — complementing insulin\'s glucose-lowering effects through an independent pathway.',dose:'15–120 mcg before meals (titrated)',freq:'Before each major meal, up to 3x daily',hl:'~48 minutes',hlh:0.8,admin:'SubQ',store:'Refrigerate unopened. In-use pen: room temperature up to 28 days.',recon:'Pre-filled pharmaceutical pen — no reconstitution needed.',bens:['FDA-approved adjunct diabetes therapy','Complementary mechanism to insulin','Modest weight loss as a secondary effect','Established, decades-long clinical safety record'],sides:['Nausea (common, especially initially)','Hypoglycemia risk when combined with insulin','Injection site reactions','Requires careful insulin dose coordination'],status:'FDA Approved',pop:32,rel:['cagrilintide','semaglutide']},
  {id:'glucagon',n:'Glucagon',fn:'Glucagon',cat:'metabolic',ov:'A foundational peptide hormone produced by the pancreas that raises blood glucose — the direct physiological counterpart to insulin. Used clinically as an emergency treatment for severe hypoglycemia and diagnostically in some imaging procedures.',mech:'Binds glucagon receptors primarily in the liver, triggering glycogenolysis (glycogen breakdown) and gluconeogenesis (new glucose production), rapidly raising blood glucose levels within minutes.',dose:'1 mg IM/SubQ/IV (emergency hypoglycemia treatment)',freq:'As needed for acute hypoglycemic episodes',hl:'~8–18 minutes',hlh:0.25,admin:'IM · SubQ · IV · Intranasal (newer formulations)',store:'Refrigerate powder kits. Some newer formulations stable at room temperature.',recon:'Traditional kits require mixing powder with supplied diluent immediately before use.',bens:['FDA-approved emergency treatment for severe hypoglycemia','Fast-acting, potentially life-saving in emergency settings','Newer ready-to-use and intranasal formulations simplify emergency administration','Foundational hormone in glucose regulation research'],sides:['Nausea and vomiting (common after administration)','Only effective if liver glycogen stores are adequate','Will not work in cases of prolonged fasting or alcohol-induced hypoglycemia','Requires prompt recognition of hypoglycemia symptoms'],status:'FDA Approved',pop:40,rel:['pramlintide','semaglutide']},
  {id:'octreotide',n:'Octreotide',fn:'Octreotide (Sandostatin)',cat:'metabolic',ov:'A synthetic analogue of somatostatin, the hormone that broadly suppresses GH, insulin, glucagon, and several digestive hormones. FDA-approved for acromegaly, carcinoid syndrome, and severe diarrhea from various causes.',mech:'Activates somatostatin receptors, broadly inhibiting the release of growth hormone, insulin, glucagon, and gastrointestinal hormones — providing a "master brake" on multiple endocrine and digestive secretory pathways simultaneously.',dose:'50–200 mcg 2-3x daily (immediate-release); monthly depot injection available',freq:'Multiple times daily (short-acting) or monthly (long-acting depot)',hl:'~1.5–2 hours (immediate-release)',hlh:1.7,admin:'SubQ · IM (depot)',store:'Refrigerate. Depot formulation reconstituted immediately before injection.',recon:'Short-acting: pre-filled or reconstituted per standard protocol. Depot: reconstitute with supplied diluent immediately before injecting.',bens:['FDA-approved for acromegaly and carcinoid syndrome','Broadly suppresses excess hormone secretion in multiple conditions','Long-acting depot option reduces dosing frequency','Well-established clinical use since the 1980s'],sides:['GI upset (common, especially initially)','Gallstone risk with long-term use','Blood sugar fluctuations','Injection site reactions'],status:'FDA Approved',pop:26,rel:['lanreotide','somatropin']},
  {id:'lanreotide',n:'Lanreotide',fn:'Lanreotide (Somatuline)',cat:'metabolic',ov:'A long-acting somatostatin analogue similar to Octreotide, offering deep-subcutaneous depot dosing as infrequently as once monthly. FDA-approved for acromegaly and certain neuroendocrine tumors.',mech:'Like Octreotide, binds somatostatin receptors to suppress excess GH, insulin, glucagon, and gastrointestinal hormone secretion — formulated as a supersaturated gel for extended, steady release from a single injection.',dose:'60–120 mg deep SubQ, once every 4 weeks',freq:'Once monthly (depot gel formulation)',hl:'~23–30 days (depot release profile)',hlh:600,admin:'Deep SubQ (depot gel)',store:'Refrigerate. Bring to room temperature before injection per protocol.',recon:'Supplied as a pre-filled, ready-to-use syringe — no reconstitution needed.',bens:['FDA-approved for acromegaly and neuroendocrine tumors','Once-monthly dosing convenience','Steady, extended hormone suppression from a single injection','Well-established alternative to Octreotide'],sides:['GI upset','Gallstone risk with long-term use','Injection site nodules','Blood sugar fluctuations'],status:'FDA Approved',pop:20,rel:['octreotide','somatropin']},
  {id:'desmopressin',n:'Desmopressin',fn:'Desmopressin (DDAVP)',cat:'research',ov:'A synthetic analogue of vasopressin (antidiuretic hormone) engineered to retain water-regulating effects while minimizing the blood-vessel-constricting effects of natural vasopressin. FDA-approved for diabetes insipidus, bedwetting, and certain bleeding disorders.',mech:'Selectively activates V2 vasopressin receptors in the kidney, increasing water reabsorption and concentrating urine, largely avoiding the V1-receptor-mediated blood pressure effects of natural vasopressin.',dose:'0.1–0.4 mg orally, or 10–40 mcg intranasally, per protocol',freq:'Once or twice daily depending on indication',hl:'~3 hours',hlh:3,admin:'Oral · Intranasal · IV (clinical)',store:'Refrigerate nasal spray. Oral tablets stable at room temperature.',recon:'Pre-formulated oral tablets or nasal spray — no reconstitution needed.',bens:['FDA-approved for diabetes insipidus and nocturnal enuresis','Also used to boost clotting factor levels in mild hemophilia/von Willebrand disease','Selective mechanism avoids blood pressure side effects of natural vasopressin','Well-established pediatric and adult safety profile'],sides:['Water retention/hyponatremia risk if fluid intake isn\'t managed','Headache','Nasal irritation (intranasal form)','Requires fluid restriction guidance during use'],status:'FDA Approved',pop:22,rel:['oxytocin']},
  {id:'calcitonin',n:'Calcitonin',fn:'Calcitonin (Salmon Calcitonin / Miacalcin)',cat:'longevity',ov:'A peptide hormone that regulates calcium balance by inhibiting bone breakdown. The salmon-derived version, structurally similar to but more potent than human calcitonin, is FDA-approved for osteoporosis and Paget\'s disease of bone.',mech:'Binds calcitonin receptors on osteoclasts (bone-resorbing cells), directly inhibiting their activity and slowing bone breakdown — helping preserve bone mineral density, particularly in postmenopausal osteoporosis.',dose:'100–200 IU/day (nasal spray or injection)',freq:'Once daily',hl:'~1 hour',hlh:1,admin:'Intranasal · SubQ · IM',store:'Refrigerate nasal spray and injectable forms.',recon:'Nasal spray is pre-formulated; injectable forms reconstituted per manufacturer instructions.',bens:['FDA-approved for osteoporosis and Paget\'s disease','Directly slows bone density loss','Long clinical history dating to the 1970s','Available in convenient nasal spray form'],sides:['Nasal irritation (spray form)','Flushing','Nausea','Long-term use has an associated cancer-risk advisory in some regulatory reviews — used at lowest effective dose'],status:'FDA Approved',pop:24,rel:['teriparatide','abaloparatide']},
  {id:'teriparatide',n:'Teriparatide',fn:'Teriparatide (Forteo)',cat:'longevity',ov:'A synthetic fragment of parathyroid hormone (PTH 1-34), notable for being one of the only osteoporosis treatments that builds new bone rather than simply slowing bone loss. FDA-approved for severe osteoporosis with high fracture risk.',mech:'Intermittent, pulsatile activation of PTH receptors on osteoblasts (bone-building cells) paradoxically stimulates new bone formation — the opposite effect of the continuous PTH elevation seen in hyperparathyroidism, which causes bone loss.',dose:'20 mcg SubQ once daily',freq:'Once daily, typically for a maximum treatment duration of 2 years',hl:'~1 hour',hlh:1,admin:'SubQ (pre-filled pen)',store:'Refrigerate. Do not freeze. Discard pen after 28 days of use.',recon:'Pre-filled pharmaceutical pen — no reconstitution needed.',bens:['FDA-approved bone-building (anabolic) osteoporosis treatment','Directly increases bone mineral density rather than just slowing loss','Reduces vertebral and non-vertebral fracture risk significantly in trials','Well-established dosing protocol'],sides:['Leg cramps','Nausea','Dizziness','Lifetime treatment duration is capped due to a bone tumor signal observed in animal studies at high lifetime exposure'],status:'FDA Approved',pop:28,rel:['abaloparatide','calcitonin']},
  {id:'abaloparatide',n:'Abaloparatide',fn:'Abaloparatide (Tymlos)',cat:'longevity',ov:'A synthetic analogue related to parathyroid hormone-related protein (PTHrP), representing a newer generation of bone-building osteoporosis treatment with a more selective receptor activation profile than Teriparatide.',mech:'Selectively activates a specific conformation of the PTH receptor associated with bone formation, aiming to maximize the anabolic (bone-building) signal while minimizing bone resorption signaling compared to older PTH-based therapies.',dose:'80 mcg SubQ once daily',freq:'Once daily, typically for a maximum treatment duration of 2 years',hl:'~1.7 hours',hlh:1.7,admin:'SubQ (pre-filled pen)',store:'Refrigerate. Do not freeze. Discard pen after use per labeling.',recon:'Pre-filled pharmaceutical pen — no reconstitution needed.',bens:['FDA-approved bone-building osteoporosis treatment','More selective receptor activation profile than Teriparatide','Significant fracture risk reduction demonstrated in trials','Newer-generation option in the anabolic bone-therapy class'],sides:['Dizziness','Nausea','Heart rate increase shortly after dosing','Same lifetime treatment duration cap as Teriparatide due to a similar animal-study safety signal'],status:'FDA Approved',pop:20,rel:['teriparatide','calcitonin']}
];

